export function test(): int {
  let max: int = 2147483647;
  let min: int = -2147483648;
  if (max !== 2147483647 || min !== -2147483648) {
    throw { code: "TEST_FAIL", message: "int32 literal boundaries must hold their exact values" };
  }
  return 0;
}

import * as console from "std/console"
export function test(): null {
  let xs: int[] = [1];
  if ((2147483647 + 1) === xs[-1]) { console.log("bad"); }
}

export function test(): int {
  let t: table = { v: 2147483648.0 };
  let n: int | null = t.v;
  if (n === null) { return 1; }
  return 0;
}

import * as math from "std/math"
export function test(): int {
  return math.absInt(-2147483648);
}

export function test(): int {
  if (2.0 ** 10.0 !== 1024.0) { throw { code: "TEST_FAIL", message: "2.0 ** 10.0 must be 1024.0" }; }
  if ((-2.0) ** 3.0 !== -8.0) { throw { code: "TEST_FAIL", message: "(-2.0) ** 3.0 must be -8.0" }; }
  if (0.0 ** 0.0 !== 1.0) { throw { code: "TEST_FAIL", message: "0.0 ** 0.0 must be 1.0" }; }
  if (0.0 ** -1.0 !== (1.0 / 0.0)) { throw { code: "TEST_FAIL", message: "0.0 ** -1.0 must be +Infinity" }; }
  if ((-2.0) ** 0.5 === (-2.0) ** 0.5) { throw { code: "TEST_FAIL", message: "negative-base fractional pow must be NaN" }; }
  if (1.0 ** (0.0 / 0.0) !== 1.0) { throw { code: "TEST_FAIL", message: "1.0 ** NaN must be 1.0" }; }
  if ((0.0 / 0.0) ** 0.0 !== 1.0) { throw { code: "TEST_FAIL", message: "NaN ** 0.0 must be 1.0" }; }
  if ((-1.0) ** (1.0 / 0.0) !== 1.0) { throw { code: "TEST_FAIL", message: "(-1.0) ** Infinity must be 1.0" }; }
  if (2.0 ** 1024.0 !== (1.0 / 0.0)) { throw { code: "TEST_FAIL", message: "2.0 ** 1024.0 must overflow to +Infinity" }; }
  if (2.0 ** -1075.0 !== 0.0) { throw { code: "TEST_FAIL", message: "2.0 ** -1075.0 must underflow to +0" }; }
  return 0;
}

